function ProjectChip(props: {
  projects: Array<{ path: string; title: string }>
  value?: string
  onChange: (path: string) => void
  embedded?: boolean
}): ReactNode {
  const [open, setOpen] = useState(false)
  const root = useRef<HTMLDivElement | null>(null)
  const current = props.projects.find(item => item.path === props.value) ?? props.projects[0]
  useEffect(() => {
    if (!open) return
    const onDoc = (event: MouseEvent) => {
      if (root.current !== null && !root.current.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener('mousedown', onDoc)
    return () => document.removeEventListener('mousedown', onDoc)
  }, [open])
  return (
    <div ref={root} style={{ position: 'relative' }}>
      <button
        className="dx-hit"
        title="当前项目（每个工作区一份画布）"
        onClick={() => setOpen(value => !value)}
        style={{
          ...(props.embedded === true ? {} : dxChrome),
          height: 32,
          padding: '0 10px 0 8px',
          borderRadius: 999,
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          maxWidth: 168,
          fontSize: 12,
          fontWeight: 500,
          background: props.embedded === true ? 'transparent' : dxChrome.background,
          border: props.embedded === true ? 'none' : dxChrome.border,
        }}
      >
        <IconFolder size={14} />
        <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {current?.title || current?.path || '项目'}
        </span>
        <IconChevron size={12} />
      </button>
      {open ? (
        <div style={{ ...menu, left: 0, top: 44, minWidth: 220 }}>
          {props.projects.map(project => (
            <button
              key={project.path}
              className="dx-menu-item"
              style={item}
              onClick={() => {
                props.onChange(project.path)
                setOpen(false)
              }}
            >
              <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis' }}>{project.title || project.path}</span>
              {project.path === props.value ? <IconCheck size={14} /> : null}
            </button>
          ))}
        </div>
      ) : null}
    </div>
  )
}

